import{_ as t,o as s,c as a,al as o}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"DroneCAN Shell","description":"","frontmatter":{},"headers":[],"relativePath":"en/debug/dronecan_shell.md","filePath":"en/debug/dronecan_shell.md"}'),n={name:"en/debug/dronecan_shell.md"};function i(l,e,r,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="dronecan-shell" tabindex="-1">DroneCAN Shell <a class="header-anchor" href="#dronecan-shell" aria-label="Permalink to &quot;DroneCAN Shell&quot;">​</a></h1><p>The DroneCAN Shell is a <a href="https://cwiki.apache.org/confluence/pages/viewpage.action?pageId=139629410" target="_blank" rel="noreferrer">NuttShell (NSH)</a> console running on a DroneCAN peripheral node (a CAN node running PX4 firmware), which you access over the CAN bus via the <code>uavcan.protocol.AccessCommandShell</code> service. It is intended for peripheral nodes that only have a CAN connection and no accessible serial debug port.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This gives you a shell on the peripheral node, not on the flight controller. To access the flight controller, use the <a href="./../debug/mavlink_shell">MAVLink Shell</a> or the <a href="./../debug/system_console">System Console</a> — see <a href="./../debug/consoles#console_vs_shell">System Console vs. Shells</a> for how they compare. If the node does not boot, the DroneCAN Shell is not available: use the node&#39;s <a href="./../debug/system_console">System Console</a> instead, if it has an accessible debug port.</p></div><h2 id="preconditions" tabindex="-1">Preconditions <a class="header-anchor" href="#preconditions" aria-label="Permalink to &quot;Preconditions&quot;">​</a></h2><p>PX4 firmware <a href="./../hardware/porting_guide_config">must be built with</a> <code>CONFIG_UAVCANNODE_COMMAND_SHELL</code> enabled. This option is part of the <code>uavcannode</code> driver (<code>CONFIG_DRIVERS_UAVCANNODE</code>), so it is only available in DroneCAN peripheral-node firmware (such as <code>ark_can-gps</code>), not on flight controllers. It is not enabled by default on any board.</p><h2 id="opening-the-shell" tabindex="-1">Opening the Shell <a class="header-anchor" href="#opening-the-shell" aria-label="Permalink to &quot;Opening the Shell&quot;">​</a></h2><h3 id="dronecan-shell-py" tabindex="-1">dronecan_shell.py <a class="header-anchor" href="#dronecan-shell-py" aria-label="Permalink to &quot;dronecan_shell.py&quot;">​</a></h3><p>Access the shell from a terminal using the <code>dronecan_shell.py</code> script.</p><h4 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h4><ul><li><p>A computer running Linux or macOS. The script uses <code>termios</code> for terminal handling, so it does not run on Windows.</p></li><li><p>A USB-CAN adapter that supports SLCAN, connected to the same CAN bus as the node.</p></li><li><p>The <code>dronecan</code> and <code>pyserial</code> Python packages:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dronecan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pyserial</span></span></code></pre></div></li></ul><h4 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h4><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/dronecan_shell.py</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">devic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--node-id </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NODE_ID]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--baudrate </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">BAUDRATE]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--bitrate </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">BITRATE]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--allocator]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Argument</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>device</code></td><td>required</td><td>Serial port of the SLCAN adapter, e.g. <code>/dev/ttyACM0</code></td></tr><tr><td><code>--node-id</code></td><td><code>100</code></td><td>DroneCAN node ID used by the script itself</td></tr><tr><td><code>--baudrate</code></td><td><code>115200</code></td><td>Serial baudrate to the adapter</td></tr><tr><td><code>--bitrate</code></td><td><code>1000000</code></td><td>CAN bus bitrate</td></tr><tr><td><code>--allocator</code></td><td>disabled</td><td>Act as a dynamic node ID allocator</td></tr></tbody></table><p>The script listens on the bus for 5 seconds, lists the nodes it finds, and asks for the ID of the one to connect to. The list includes every node on the bus, such as the flight controller and ESCs, but only PX4 peripheral nodes built with <code>CONFIG_UAVCANNODE_COMMAND_SHELL</code> provide a shell.</p><p>If you select a node that does not provide a shell, the script prints the <code>node &lt;id&gt;: Ctrl-C interrupts, Ctrl-D goes back</code> banner and then nothing else. No <code>nsh&gt;</code> prompt appears and no error is reported, because the node silently ignores the shell requests. Press <strong>Ctrl+D</strong> to return to the node list.</p><p>In the shell, <strong>Ctrl+C</strong> resets the shell (it starts a new NSH session rather than interrupting the running command), and <strong>Ctrl+D</strong> returns to the node list. Arrow keys, command history and tab completion are not supported (arrow keys insert stray characters such as <code>[A</code> into the line).</p><h4 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h4><p>Flight controller connected to the bus, already allocating dynamic node IDs:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/dronecan_shell.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span></span></code></pre></div><p>No other allocator on the bus, so the script must allocate an ID for the target node:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/dronecan_shell.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allocator</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don&#39;t use <code>--allocator</code> if the flight controller or any other node is already allocating IDs on the same bus. Two allocators racing can assign conflicting IDs.</p></div><h2 id="using-the-dronecan-shell" tabindex="-1">Using the DroneCAN Shell <a class="header-anchor" href="#using-the-dronecan-shell" aria-label="Permalink to &quot;Using the DroneCAN Shell&quot;">​</a></h2><p>For information see: <a href="./../debug/consoles#using_the_console">PX4 Consoles/Shells &gt; Using Consoles/Shells</a>.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Only one shell session per node: a request from another client node closes the current shell and starts a new one.</li><li>The output buffer is just the pipe&#39;s current buffer, not a persistent per-command output store.</li><li><code>FLAG_CLEAR_OUTPUT_BUFFERS</code>, <code>FLAG_READ_STDERR</code>, <code>FLAG_READ_STDOUT</code>, <code>FLAG_RUNNING</code>, <code>FLAG_HAS_PENDING_STDERR</code> are not implemented.</li><li><code>last_exit_status</code> is not reported (always 0).</li><li>There is no separate stderr stream: stderr is redirected to stdout.</li></ul>',26)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
